function exerciseArtwork(name='',muscle='',representative=false){const n=name.toLowerCase();if(/incline.*barbell|barbell.*incline/.test(n))return {sheet:'press',index:0};if(/barbell.*(bench|chest)|flat.*barbell/.test(n))return {sheet:'press',index:1};if(/smith.*shoulder|shoulder.*smith/.test(n))return {sheet:'press',index:2};if(/hanging.*leg/.test(n))return {sheet:'press',index:3};const matches=[[/hammer/,5],[/curl/,4],[/pushdown/,6],[/romanian|deadlift/,8],[/squat/,7],[/leg extension/,9],[/lateral raise/,11],[/reverse pec|rear.*fly/,12],[/face pull/,13],[/pulldown/,2],[/row/,1],[/chest fly|pec deck/,3],[/dumbbell.*(chest|bench)|(chest|bench).*dumbbell/,0],[/shoulder press|overhead.*dumbbell/,10],[/knee raise/,14]];return {sheet:'movement',index:matches.find(([pattern])=>pattern.test(n))?.[1]??(representative?partArtwork[muscle]??15:15)}}
