function renderCalendar(){today=new Date();const todayKey=C.dateKey(today),prefix=C.dateKey(view).slice(0,7),end=prefix+'-'+new Date(view.getFullYear(),view.getMonth()+1,0).getDate(),to=end<todayKey?end:todayKey;const from=prefix+'-01',stats=C.summarize(state,from,to),sessions=C.activeSessions(state,from,to),most=Math.max(...Object.values(stats.parts)),favorites=most?C.parts.filter(part=>stats.parts[part]===most):[],favorite=favorites[0],streak=longestStreak(sessions);$('#calendar-stats').innerHTML=stat('WORKOUT DAYS',stats.days,'this month')+stat('FAV BODY PART',favorite?esc(favorite):'—',favorite?`${most} ${most===1?'day':'days'}`:'this month',favorite?favorites.length>1?`Tied with ${esc(favorites.slice(1).join(', '))}.`:'':'No workouts this month.')+stat('LONGEST STREAK',streak,streak===1?'day in a row':'days in a row','');$('#month').textContent=view.toLocaleDateString('en-US',{month:'long'});$('#year').textContent=view.getFullYear();const start=new Date(view);start.setDate(1-(view.getDay()+6)%7);const total=Math.ceil(((view.getDay()+6)%7+new Date(view.getFullYear(),view.getMonth()+1,0).getDate())/7)*7;let html='';for(let i=0;i<total;i++){const d=new Date(start);d.setDate(start.getDate()+i);const date=C.dateKey(d),s=state.sessions.find(s=>s.date===date),parts=s?C.sessionParts(s):[];html+=`<button class="day ${d.getMonth()!==view.getMonth()?'other':''} ${date===selected?'selected':''} ${date===todayKey?'is-today':''}" data-date="${date}" aria-label="${esc(fmt(date,{weekday:'long',month:'long',day:'numeric',year:'numeric'}))}${parts.length?', '+esc(parts.join(', ')):', no entry'}" title="Double-click to open workout"><span class="number">${d.getDate()}</span>${parts.length?'<i class="day-mark"></i>':''}${parts.slice(0,2).map(pill).join('')}${parts.length>2?`<span class="more">+${parts.length-2} more</span>`:''}</button>`}$('#calendar').innerHTML=html;$('#legend').innerHTML=C.parts.map(m=>`<span style="${css(m)}"><i></i>${m}</span>`).join('');renderDay()}
function renderDay(){$('#day-title').textContent=fmt(selected,{weekday:'short',month:'long',day:'numeric'});const s=session(),parts=s?C.sessionParts(s):[],sets=s?.exercises.reduce((n,e)=>n+C.recordedSets(e).length,0)||0,logged=s?.exercises.filter(e=>C.recordedSets(e).length)||[];$('#day-content').innerHTML=parts.length?`<div class="day-focus">${exerciseVisual(s.exercises[0]?.name||'',parts[0],'focus-art',true)}<div><h3>${esc(parts.join(' + '))}</h3></div></div><div class="tag-row">${parts.map(pill).join('')}</div><div class="day-summary"><div><strong>${logged.length}</strong>exercises logged</div><div><strong>${sets}</strong>sets recorded</div></div>${logged.slice(0,3).map(e=>`<div class="mini-exercise">${exerciseVisual(e.name,e.muscle)}<div><strong>${esc(e.name)}</strong><span>${e.sets.length} ${e.sets.length===1?'set':'sets'} · ${esc(e.sets[0]?.unit==='bodyweight'?'Bodyweight':unitsLabel[e.sets[0]?.unit]||'')}</span></div></div>`).join('')}${s.notes?`<p class="quiet">${esc(s.notes)}</p>`:''}`:`<div class="empty-day">${exerciseVisual('','','empty-art')}<h3>No workout logged</h3></div>`;const pending=state.review.filter(r=>!r.resolvedDate).reduce((n,r)=>n+r.exercises.reduce((sets,e)=>sets+e.sets.length,0),0);$('#review-shortcut').textContent=pending?`Confirm ${pending} undated sets ↗`:'';$('#review-shortcut').hidden=!pending}
