function renderExerciseUnits(){const {from,to}=range(),name=insightExercise,prev=$('#unit-select').value;const units=[...new Set(C.activeSessions(state,from,to).flatMap(s=>s.exercises.filter(e=>e.name===name).flatMap(e=>e.sets.map(t=>t.unit))))];$('#unit-select').disabled=!units.length;$('#unit-select').hidden=units.length<2;$('#unit-select').innerHTML=units.map(u=>`<option value="${u}">${esc(unitsLabel[u])}</option>`).join('');if(units.includes(prev))$('#unit-select').value=prev;renderExerciseProgress()}
function renderExerciseProgress(){const {from,to}=range(),name=insightExercise,unit=$('#unit-select').value,points=C.exerciseHistory(state,name,unit,from,to),exercise=state.sessions.flatMap(s=>s.exercises).find(e=>e.name===name),art=exerciseVisual(exercise?name:'',exercise?.muscle||'','progress-art');const visual=`<div class="progress-visual">${art}<div class="progress-identity">${exercise?pill(exercise.muscle):''}<h3>${esc(exercise?name:'Exercise progress')}</h3></div></div>`;if(!points.length){$('#exercise-progress').innerHTML=`<div class="progress-layout">${visual}<div class="chart-empty">${exercise?'Add the missing weight or reps to view progress.':'No exercises logged for this period.'}</div></div>`;return}const last=points.at(-1),first=points[0],value=unit==='bodyweight'?last.reps:last.load,delta=unit==='bodyweight'?last.reps-first.reps:last.load-first.load,best=Math.max(...points.map(p=>unit==='bodyweight'?p.reps:p.load)),suffix=unit==='bodyweight'?'reps':unit,comparison=points.length>1?`${delta>0?'+':''}${Math.round(delta*100)/100} ${suffix} since ${fmt(first.date)}`:fmt(first.date,{month:'short',day:'numeric',year:'numeric'});$('#exercise-progress').innerHTML=`<div class="progress-layout">${visual}<div class="progress-data"><div class="progress-metrics"><div><span>Latest</span><strong>${value}<small>${esc(suffix)}</small></strong></div><div><span>Best</span><strong>${best}<small>${esc(suffix)}</small></strong></div><div><span>Workouts</span><strong>${points.length}</strong></div></div><div class="progress-comparison ${delta>0?'positive':''}">${esc(comparison)}</div>${trend(points.map(p=>({date:p.date,value:unit==='bodyweight'?p.reps:p.load,detail:unit==='bodyweight'?p.reps+' reps':p.reps+' reps'})))}<span class="chart-measure">${unit==='bodyweight'?'Most reps per workout':'Heaviest set per workout'}</span></div></div>`}

function trend(points){const list=points.slice(-8),max=Math.max(...list.map(p=>p.value),1);return `<div class="trend-points">${list.map(p=>`<div class="trend-point"><strong>${p.value}</strong><i style="height:${Math.max(3,p.value/max*100)}px"></i></div>`).join('')}</div><div class="trend-caption">${list.map(p=>`<div>${esc(fmt(p.date))}<small>${esc(p.detail)}</small></div>`).join('')}</div>`}
function renderWeight(){const {from,to}=range(),measurements=state.measurements.filter(m=>m.date>=from&&m.date<=to).sort((a,b)=>a.date.localeCompare(b.date));$('#weight-insight').innerHTML=measurements.length?`<div class="weight-value">${measurements.at(-1).weight}<small>kg · ${esc(fmt(measurements.at(-1).date))}</small></div>${trend(measurements.map(m=>({date:m.date,value:m.weight,detail:'kg'})))}${''}`:`<div class="weight-value">${state.profile.baselineWeight??'—'}<small>kg · undated</small></div><p class="quiet">Add a measurement to track changes.</p>`}
function renderReview(){$('#review-list').innerHTML=state.review.map(r=>`<article class="review-item"><div class="split"><h3>${esc(r.title)}</h3><span class="review-status">${r.resolvedDate?'Assigned to '+esc(fmt(r.resolvedDate)):r.exercises.length?'Date uncertain':r.kind==='plan'?'Plan, not completed':'Unclear report'}</span></div><p>Reported ${esc(fmt(r.reportedDate,{month:'short',day:'numeric',year:'numeric'}))}${r.exercises.length?' · '+r.exercises.reduce((n,e)=>n+e.sets.length,0)+' confirmed sets':''}</p>${r.exercises.length?`<div class="tag-row">${r.exercises.map(e=>`<span class="pill">${esc(e.name)} · ${e.sets.length} sets</span>`).join('')}</div>`:''}<details><summary>Original notes</summary><p>${esc(r.notes)}</p></details>${r.exercises.length&&!r.resolvedDate?`<button class="text-button" data-resolve="${esc(r.id)}">Confirm workout date ↗</button>`:''}</article>`).join('')}
function renderProfile(fill=true){if(fill){$('#profile-height').value=state.profile.height??'';$('#profile-experience').value=state.profile.experience;$('#profile-goals').value=state.profile.goals;$('#profile-equipment').value=state.profile.equipment;$('#profile-pain').value=state.profile.painNote}$('#baseline').innerHTML=`<div class="baseline-card">Starting weight · undated<strong>${state.profile.baselineWeight??'—'} kg</strong></div>`;$('#measurements').innerHTML=state.measurements.length?[...state.measurements].sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<div class="measurement-row"><div>${esc(fmt(m.date,{month:'short',day:'numeric',year:'numeric'}))}<small>${[m.waist?'Waist '+m.waist+' cm':'',m.arm?'Arm '+m.arm+' cm':''].filter(Boolean).join(' · ')||'Bodyweight check-in'}</small></div><div class="measurement-value">${m.weight}<small>kg</small></div><button data-edit-measurement="${m.date}">Edit</button></div>`).join(''):'<div class="no-data">No measurements yet.</div>';renderTemplates()}
function renderTemplates(){$('#template-tabs').innerHTML=C.parts.map(m=>`<button data-template-part="${m}" class="${m===templatePart?'active':''}">${m}</button>`).join('');$('#template-list').innerHTML=state.templates[templatePart].length?state.templates[templatePart].map(t=>`<div class="template-item">${exerciseVisual(t.name,templatePart)}<div class="template-name">${esc(t.name)}<small>${esc(unitsLabel[t.unit])}</small></div><div class="template-actions"><button data-edit-template="${esc(t.id)}">Edit</button><button data-remove-template="${esc(t.id)}" aria-label="Remove ${esc(t.name)} default">×</button></div></div>`).join(''):'<p class="no-data">Add your usual exercises for '+templatePart.toLowerCase()+'.</p>'}
