function exportData(){if(storageBlocked){notify('Current saved data is unreadable. Restore a known Gym backup to continue.');return}const data=JSON.stringify(state,null,2);if(window.webkit?.messageHandlers?.exportHistory){window.webkit.messageHandlers.exportHistory.postMessage(data);return}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.download='gym-journal-'+C.dateKey(new Date())+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
