$('#exercise-list').onclick=e=>{const extra=e.target.closest('[data-extra-set]'),edit=e.target.closest('[data-edit-exercise]'),remove=e.target.closest('[data-remove-exercise]'),removeSet=e.target.closest('[data-remove-set]');if(extra){const ex=session().exercises.find(e=>e.id===extra.dataset.extraSet),card=extra.closest('.exercise-card'),unit=ex.unit||ex.sets[0]?.unit||'kg';const rows=card.querySelector('.inline-sets');const values=[...rows.querySelectorAll('.inline-set')].map(r=>({load:r.querySelector('[data-field="load"]').value===''?null:Number(r.querySelector('[data-field="load"]').value),reps:r.querySelector('[data-field="reps"]').value===''?null:Number(r.querySelector('[data-field="reps"]').value),unit}));rows.innerHTML=inlineRows({...ex,sets:[...values,{load:null,reps:null,unit}]});rows.lastElementChild.querySelector(unit==='bodyweight'?'[data-field="reps"]':'[data-field="load"]').focus();return}if(edit){showExercise(session().exercises.find(x=>x.id===edit.dataset.editExercise));return}if(remove){const ex=session().exercises.find(x=>x.id===remove.dataset.removeExercise);const apply=()=>{if(change(state=>C.ensureSession(state,selected).exercises=C.ensureSession(state,selected).exercises.filter(x=>x.id!==ex.id))){render();renderExercises()}};ex.sets.length?confirmAction('Remove this exercise?','The sets for '+ex.name+' on this day will be removed. Your default routine will stay as it is.',apply,'Remove'):apply();return}if(removeSet){const exId=removeSet.dataset.exId,index=Number(removeSet.dataset.removeSet);const apply=()=>{if(change(state=>{const ex=C.ensureSession(state,selected).exercises.find(x=>x.id===exId);ex.sets.splice(index,1)})){render();renderExercises()}};const ex=session().exercises.find(x=>x.id===exId);ex.sets[index]&&(ex.sets[index].load!==null||ex.sets[index].reps!==null)?confirmAction('Remove this set?','The weight and reps for this set will be removed.',apply,'Remove'):apply()}};
