$('#exercise-form').onsubmit=e=>{e.preventDefault();const name=$('#exercise-name').value.trim();if(!name){$('#exercise-error').textContent='Give this exercise a name.';return}const muscle=$('#exercise-muscle').value,unit=$('#exercise-unit').value,notes=$('#exercise-notes').value.trim();if(exerciseMode==='template'){if(change(state=>{const ts=state.templates[templatePart];if(ts.some(t=>t.id!==editingExercise&&t.name.toLowerCase()===name.toLowerCase()))throw Error('duplicate');const t={id:editingExercise||id(),name,unit,notes};const i=ts.findIndex(t=>t.id===editingExercise);i<0?ts.push(t):ts.splice(i,1,t)})){$('#exercise-editor').close();renderTemplates();notify('Default updated for future workouts.')}return}const sets=rawFormRows().map(t=>({...t,load:unit==='bodyweight'?null:t.load})).filter(t=>t.load!==null||t.reps!==null);const exercise={id:editingExercise||id(),name,muscle,unit,notes,pain:$('#exercise-pain').checked,sets};if(change(state=>{const s=C.ensureSession(state,selected),i=s.exercises.findIndex(e=>e.id===editingExercise);i<0?s.exercises.push(exercise):s.exercises.splice(i,1,exercise);s.muscles=[...new Set([...s.muscles,muscle])]})){$('#exercise-editor').close();render();renderWorkout()}};
